import asyncio
from typing import Any
import httpx
from fastmcp import FastMCP


def create_mcp_server_from_openapi(
    spec: dict,
    client: httpx.AsyncClient
) -> FastMCP:
    """Create an MCP server from OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 spec as a Python dict
        client: Pre-configured httpx.AsyncClient with base_url set

    Returns:
        FastMCP server instance with tools for each operation
    """
    server = FastMCP("OpenAPI MCP Server")

    tools_to_register = []

    for path, path_item in spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "patch", "delete", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path}")
            summary = operation.get("summary", "")

            input_schema: dict[str, Any] = {
                "type": "object",
                "properties": {},
                "required": []
            }

            for param in operation.get("parameters", []):
                name = param["name"]
                input_schema["properties"][name] = param.get("schema", {"type": "string"})
                if param.get("required"):
                    input_schema["required"].append(name)

            request_body = operation.get("requestBody")
            if request_body:
                body_schema = (
                    request_body
                    .get("content", {})
                    .get("application/json", {})
                    .get("schema", {})
                )
                if body_schema:
                    input_schema["properties"]["body"] = body_schema
                    if request_body.get("required"):
                        input_schema["required"].append("body")

            def make_handler(p: str, m: str):
                async def endpoint(**kwargs: Any) -> Any:
                    url = p
                    for key in list(kwargs.keys()):
                        if "{" + key + "}" in url:
                            url = url.replace("{" + key + "}", str(kwargs.pop(key)))

                    body = kwargs.pop("body", None)
                    req_kw = {"json": body} if body is not None else {}

                    resp = await client.request(m.upper(), url, **req_kw)
                    resp.raise_for_status()
                    return resp.json()

                return endpoint

            tools_to_register.append({
                "id": operation_id,
                "summary": summary or operation_id,
                "handler": make_handler(path, method)
            })

    for tool_info in tools_to_register:
        def register_factory(tool_id, tool_summary, handler_func):
            @server.tool()
            async def tool_impl(**kwargs: Any) -> Any:
                return await handler_func(**kwargs)

            tool_impl.__name__ = tool_id
            tool_impl.__doc__ = tool_summary

        register_factory(tool_info["id"], tool_info["summary"], tool_info["handler"])

    return server


async def main():
    openapi_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0"},
        "paths": {
            "/items": {
                "get": {
                    "operationId": "listItems",
                    "summary": "List all items",
                    "responses": {"200": {"description": "OK"}}
                },
                "post": {
                    "operationId": "createItem",
                    "summary": "Create new item",
                    "requestBody": {
                        "required": True,
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "object",
                                    "properties": {"name": {"type": "string"}},
                                    "required": ["name"]
                                }
                            }
                        }
                    },
                    "responses": {"201": {"description": "Created"}}
                }
            },
            "/items/{id}": {
                "get": {
                    "operationId": "getItem",
                    "summary": "Get item by ID",
                    "parameters": [
                        {
                            "name": "id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "string"}
                        }
                    ],
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = create_mcp_server_from_openapi(openapi_spec, client)
        async with server:
            await server.wait_for_shutdown()


if __name__ == "__main__":
    asyncio.run(main())

